[
  {
    "role": "feature_screenshot",
    "url": "https://github.com/carbon-design-system/carbon/issues/22307",
    "local_path": "/app/.harbor_assets/date_time_formats_reference.png",
    "description": "The issue's own attachment: the design-guidance table of the date/time formats the utilities already support (Relative time, Absolute time, Absolute date, Absolute date and time, Date and time tooltip), each row showing reference output in en-US/de-DE/es-ES, the permitted style variants, and which variant is the default. It has no Duration row - the gap the issue asks to fill - and it is the correctness reference the two current-state screenshots are meant to be read against."
  },
  {
    "role": "bug_screenshot",
    "url": "https://github.com/carbon-design-system/carbon/issues/22307",
    "local_path": "/app/.harbor_assets/datetime_utilities_current.png",
    "description": "The date & time utilities demo rendered from the task's base state (real calls into the package source, fixed clock, timeZone UTC, en-US/de-DE/es-ES side by side; default-option calls paired with explicit-style calls). Six injected faults are visible: '50 seconds ago' renders '0 minutes ago' beside a 30-second row that correctly says 'now' (the under-a-minute window was narrowed); default-option relative output renders in the short style beside an explicit-long row and a guidance table that says long is the default; the de-DE and es-ES cells of the sub-minute row render in English while neighbouring locale cells are correct (locale dropped on that path); every default-option absolute time shows seconds (default drifted short->medium); every default-option absolute date shows the spelled-out month (default drifted medium->long); and the de-DE/es-ES cells of the range row render in English (locale dropped in the range path). The duration section shows 'not provided by the utilities yet'."
  },
  {
    "role": "bug_screenshot",
    "url": "https://github.com/carbon-design-system/carbon/issues/22307",
    "local_path": "/app/.harbor_assets/tag_overflow_current.png",
    "description": "The tag-overflow utility demo rendered from the task's base state, four captioned rows. Two injected faults are visible: rows that overflow have lost their dark '+N' indicator entirely (its visibility toggle is inverted), and the row captioned 'maxVisibleItems: 3' shows five tags (the cap is ignored once the container overflows). Correct sibling rows ('everything fits', and the all-fit maxVisibleItems row) sit directly beside the broken ones."
  }
]

