165	+/**
166	+ * Copyright IBM Corp. 2026
167	+ *
168	+ * This source code is licensed under the Apache-2.0 license found in the
169	+ * LICENSE file in the root directory of this source tree.
170	+ *
171	+ * Behavioural checks for the overflow handler's contract when a container
172	+ * overflows: the maxVisibleItems cap must hold, and the overflow indicator
173	+ * (the data-offset element) must be revealed exactly when items are hidden.
174	+ * Sizes are mocked the same way the module's own test file mocks them; the
175	+ * handler's asynchronous update is awaited, never assumed synchronous.
176	+ */
177	+
178	+import { createOverflowHandler } from './overflowHandler';
179	+
180	+// jsdom has no ResizeObserver; the handler's initial update runs through
181	+// requestAnimationFrame (which jsdom does provide), so a construct-only stub is
182	+// all these behavioural checks need.
183	+if (typeof globalThis.ResizeObserver === 'undefined') {
184	+  globalThis.ResizeObserver = class {
185	+    observe() {}
186	+    unobserve() {}
187	+    disconnect() {}
188	+  };
189	+}
190	+
191	+const createItems = (sizes) =>
192	+  sizes.map((size) => {
193	+    const item = document.createElement('div');
194	+    Object.defineProperty(item, 'getBoundingClientRect', {
195	+      value: () => ({ width: size }),
196	+    });
197	+    return item;
198	+  });
199	+
200	+const setContainerWidth = (container, value) => {
201	+  Object.defineProperty(container, 'clientWidth', {
202	+    value,
203	+    configurable: true,
204	+    writable: true,
205	+  });
206	+};
207	+
208	+const nextChange = (register) =>
209	+  new Promise((resolve) => register(resolve));
210	+
211	+describe('overflow contract', () => {
212	+  let container;
213	+  let handler;
214	+
215	+  beforeEach(() => {
216	+    container = document.createElement('div');
217	+  });
218	+
219	+  afterEach(() => {
220	+    if (handler) {
221	+      handler.disconnect();
222	+      handler = null;
223	+    }
224	+  });
225	+
226	+  test('maxVisibleItems caps the visible set when the container overflows', async () => {
227	+    container.append(...createItems(Array(10).fill(40)));
228	+    setContainerWidth(container, 200);
229	+
230	+    let report;
231	+    const changed = new Promise((resolve) => {
232	+      report = resolve;
233	+    });
234	+    handler = createOverflowHandler({
235	+      container,
236	+      maxVisibleItems: 3,
237	+      onChange: (visible, hidden) => report([visible, hidden]),
238	+    });
239	+
240	+    const [visible, hidden] = await changed;
241	+    expect(visible.length).toBe(3);
242	+    expect(hidden.length).toBe(7);
243	+  });
244	+
245	+  test('the overflow indicator is revealed while items are hidden', async () => {
246	+    const items = createItems(Array(10).fill(40));
247	+    container.append(...items);
248	+
249	+    const offset = document.createElement('span');
250	+    offset.setAttribute('data-offset', '');
251	+    offset.setAttribute('data-hidden', ''); // authored hidden, like a consumer would
252	+    Object.defineProperty(offset, 'getBoundingClientRect', {
253	+      value: () => ({ width: 40 }),
254	+    });
255	+    container.appendChild(offset);
256	+
257	+    setContainerWidth(container, 200);
258	+
259	+    const changed = new Promise((resolve) => {
260	+      handler = createOverflowHandler({
261	+        container,
262	+        onChange: (visible, hidden) => resolve([visible, hidden]),
263	+      });
264	+    });
265	+
266	+    const [, hidden] = await changed;
267	+    expect(hidden.length).toBeGreaterThan(0);
268	+    // Items are hidden, so the indicator itself must be visible.
269	+    expect(offset.hasAttribute('data-hidden')).toBe(false);
270	+    // The hidden items are marked; visible ones are not.
271	+    hidden.forEach((item) => {
272	+      expect(item.hasAttribute('data-hidden')).toBe(true);
273	+    });
274	+  });
